package main

import (
	&quot;context&quot;
	&quot;fmt&quot;
	&quot;math&#47;rand&quot;
	&quot;sync&quot;
	&quot;time&quot;
)

type RPCService struct {
	Name string
}

func (s *RPCService) Call(ctx context.Context) error {
	sleepTime := time.Duration(100+rand.Intn(400)) * time.Millisecond
	select {
	case &lt;-time.After(sleepTime):
		if rand.Intn(3) == 0 {
			return fmt.Errorf(&quot;call RPC %s failed&quot;, s.Name)
		}
		fmt.Printf(&quot;call RPC %s success with TraceID: %s\n&quot;, s.Name, ctx.Value(&quot;TraceId&quot;))
	case &lt;-ctx.Done():
		fmt.Printf(&quot;call RPC %s canceled\n&quot;, s.Name)
		return fmt.Errorf(&quot;call RPC %s canceled&quot;, s.Name)
	}

	return nil
}

func main() {
	&#47;&#47; 派生一个有500ms超时时间的上下文
	ctx, cancel := context.WithTimeout(context.Background(), 500*time.Millisecond)

	&#47;&#47; 派生一个传递 TraceId 的上下文
	ctx = context.WithValue(ctx, &quot;TraceId&quot;, &quot;123456&quot;)

	&#47;&#47; 创建ABC三个RPC调用
	clients := []*RPCService{
		{Name: &quot;RPC-A&quot;},
		{Name: &quot;RPC-B&quot;},
		{Name: &quot;RPC-C&quot;},
	}

	wg := sync.WaitGroup{}

	&#47;&#47; 在子协程中调用 RPC
	for _, client := range clients {
		wg.Add(1)
		go func(client *RPCService) {
			defer wg.Done()
			&#47;&#47; 调用 RPC
			err := client.Call(ctx)
			if err != nil {
				cancel() &#47;&#47; 调用失败，取消上下文
			}
		}(client)
	}

	wg.Wait() &#47;&#47; 等待所有子协程结束

}

package main

import (
	&quot;context&quot;
	&quot;fmt&quot;
	&quot;math&#47;rand&quot;
	&quot;sync&quot;
	&quot;time&quot;
)

type RPCRequest struct {
	Id int
}
type RPCResponse struct {
	Data string
}

func callRPC(ctx context.Context, service string, req RPCRequest) (*RPCResponse, error) {
	var delay = time.Duration(rand.Intn(100)) * time.Millisecond
	select {
	case &lt;-ctx.Done():
		fmt.Printf(&quot;%s call timeout: %v\n&quot;, service, ctx.Err())
		return nil, ctx.Err()
	case &lt;-time.After(delay):
		return &amp;RPCResponse{
			Data: fmt.Sprintf(&quot;%s-%d&quot;, service, req.Id),
		}, nil
	}
}

func Run(ctx context.Context, serviceList []string, req RPCRequest) {
	ctx, cancel := context.WithTimeout(ctx, 500*time.Millisecond)
	defer cancel()

	var wg sync.WaitGroup

	for _, v := range serviceList {
		wg.Add(1)
		go func(ctx context.Context, service string) {
			defer wg.Done()
			resp, err := callRPC(ctx, service, RPCRequest{
				Id: req.Id,
			})
			if err != nil {
				fmt.Printf(&quot;%s call failed: %v\n&quot;, service, err)
				return
			}
			fmt.Printf(&quot;%s call success: %v\n&quot;, service, resp)
		}(ctx, v)
	}
	wg.Wait()
}

func main() {
	serviceList := []string{&quot;serve 1&quot;, &quot;serve 2&quot;, &quot;serve 3&quot;}
	req := RPCRequest{
		Id: 1,
	}
	Run(context.Background(), serviceList, req)
}
